import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { recoveryAdvice, type TargetState } from "../../src/domain/closed-issue.ts";

const CLOSED: TargetState = { kind: "closed", merged: false };
const MERGED: TargetState = { kind: "closed", merged: true };

/**
 * The route each case offers, taken from the advice rather than restated here.
 *
 * A literal in this file would be a third copy of a fact that already has two — the
 * function and the page — and the one that goes stale first is the one nothing reads.
 */
function routeOf(advice: string, pattern: RegExp, what: string): string {
  const match = pattern.exec(advice);
  expect(match, `${what} is not in the advice any more: ${advice}`).not.toBeNull();
  return match![0];
}

/** The rows of the symptom table, as the lines a reader sees. */
function troubleshootingRows(): string[] {
  const page = readFileSync("docs/operations.md", "utf8").replaceAll("\r\n", "\n");
  const heading = page.indexOf("## Symptom-based troubleshooting");
  expect(heading, "the troubleshooting table is gone from docs/operations.md").toBeGreaterThan(-1);
  return page
    .slice(heading)
    .split("\n")
    .slice(1)
    .sliceWhile((line) => !line.startsWith("## "))
    .filter((line) => line.startsWith("|"))
    .filter((line) => !/^\|\s*-+/.test(line) && !line.startsWith("| Symptom "));
}

describe("the troubleshooting row for a refused hand-off", () => {
  const row = troubleshootingRows().find(
    (line) => /\bclosed\b/i.test(line) && /\bmerged\b/i.test(line),
  );

  test("a row says a closed target is why a hand-off did not start", () => {
    expect(
      row,
      "no row names a closed (or merged) target as the cause of a hand-off that did not start",
    ).toBeDefined();
  });

  test("it offers the route a closed issue gets", () => {
    const reopen = routeOf(recoveryAdvice(CLOSED, 803, "/engineer"), /Reopen/, "the reopen route");
    expect(row!.toLowerCase()).toContain(reopen.toLowerCase());
  });

  /**
   * The case that costs a reader something. A row that says only "reopen it" is
   * wrong for a merged pull request, and GitHub offers no way to reopen one.
   */
  test("it keeps the merged case apart, with the route that case gets", () => {
    const instead = routeOf(recoveryAdvice(MERGED, 826, "/engineer"), /Open an issue/, "the follow-up route");
    expect(row!.toLowerCase()).toContain(instead.toLowerCase());
    expect(row!, "the merged case is the one that cannot be reopened").toMatch(/merged pull request/i);
  });
});
